// values. Anything that came from a pasted log, an imported file or saved
// settings must go through this before it is put in an innerHTML string.
const HTML_ESCAPES = { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;', '`': '&#96;' };
